// Some portions generated by Claude.
package io.github.djclarke.eclipselink.mcp;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.math.BigDecimal;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import java.util.Set;

import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;

import io.github.djclarke.eclipselink.mcp.definition.DefinitionLoader;
import io.github.djclarke.eclipselink.mcp.model.ModelRuntime;
import io.github.djclarke.eclipselink.mcp.tools.ToolException;
import io.github.djclarke.eclipselink.mcp.tools.ToolService;

/**
 * The AdventureWorks sample (samples/adventureworks): one definition, read-only for callers without writes
 * and with four write tools for those allowed them. The offline check runs in every build. The database tests
 * run only when {@code AW_DB_URL} points at the sample's PostgreSQL database (its README), with the PostgreSQL
 * driver in samples/adventureworks/drivers: they change data, so reset the database afterwards.
 */
class AdventureWorksSampleTest {

    static final Path SAMPLE = Path.of("samples/adventureworks");
    static final Path DEFINITION = SAMPLE.resolve("definition");

    @Test
    void oneDefinitionWithFourWriteOperations() {
        var definition = new DefinitionLoader(Map.of("AW_DB_PASSWORD", "unused")::get).load(DEFINITION);
        assertEquals(Set.of("create_sales_order", "update_sales_order", "add_order_line", "update_email_address"),
                Set.copyOf(definition.writes().stream().map(w -> w.name()).toList()));
        assertEquals(Set.of("SalesOrderHeader", "SalesOrderDetail", "EmailAddress"),
                definition.descriptor().tools().writes().keySet());
    }

    @Nested
    @EnabledIfEnvironmentVariable(named = "AW_DB_URL", matches = ".+")
    class OnPostgreSQL {

        static ModelRuntime start() {
            Map<String, String> env = Map.of("AW_DB_URL", System.getenv("AW_DB_URL"),
                    "AW_DB_PASSWORD", "adventureworks");
            return ModelRuntime.start(new DefinitionLoader(env::get).load(DEFINITION));
        }

        @Test
        void readOnlyCallerGetsReportsAndQueries() {
            try (ModelRuntime model = start()) {
                ToolService tools = new ToolService(model, false, false); // --writes none: a read-only caller
                assertTrue(tools.exposedWrites().isEmpty(), "no write tools");
                assertFalse(tools.tools().stream().anyMatch(t -> t.name().equals("create_sales_order")));
                List<?> rows = (List<?>) tools.call("report_sales_by_territory",
                        Map.of("fromDate", "2024-07-01T00:00:00", "toDate", "2025-07-01T00:00:00")).get("rows");
                assertEquals(10, rows.size(), "one row per territory");
                Map<?, ?> top = (Map<?, ?>) rows.get(0);
                assertEquals("North America", top.get("territoryGroup"), "a reserved word column (\"group\")");

                List<?> prices = (List<?>) tools.call("query_list_price_history", Map.of("productId", 707)).get("items");
                assertEquals(3, prices.size());
                assertEquals(null, ((Map<?, ?>) prices.get(2)).get("endDate"), "the current price");

                List<?> open = (List<?>) tools.call("query_open_orders", Map.of()).get("items");
                assertFalse(open.isEmpty(), "overlay.sql seeds open orders");
            }
        }

        @Test
        void placeAnOrderThenShipItWhileALineIsAdded() {
            try (ModelRuntime model = start()) {
                ToolService tools = new ToolService(model); // a caller allowed to write
                assertEquals(Set.of("create_sales_order", "update_sales_order", "add_order_line",
                                "update_email_address"),
                        Set.copyOf(tools.exposedWrites().stream().map(w -> w.definition().name()).toList()));

                // Store customer 29490 (Bicycle Accessories and Kits) and its main office address.
                List<?> addresses = (List<?>) tools.call("query_customer_addresses",
                        Map.of("businessEntityId", 304)).get("items");
                Object address = ((Map<?, ?>) addresses.get(0)).get("addressId");
                Map<String, Object> created = tools.call("create_sales_order", Map.of("customer", 29490,
                        "billToAddress", address, "shipToAddress", address, "shipMethod", 5,
                        "dueDate", java.time.LocalDate.now().plusDays(12) + "T00:00:00",
                        "lines", List.of(Map.of("product", 707, "orderQty", 3), Map.of("product", 711, "orderQty", 2))));
                Map<?, ?> order = (Map<?, ?>) created.get("item");
                Object id = order.get("salesOrderId");
                assertEquals(1, ((Number) order.get("status")).intValue());
                assertEquals(1, ((Number) order.get("revisionNumber")).intValue());
                assertEquals(0, new BigDecimal("174.95").compareTo(new BigDecimal((String) order.get("totalDue"))),
                        "5 units at 34.99, the current list price");

                // B ships the order; A, who read revision 1, then adds a line. A check constraint keeps the ship
                // date on or after the order date, which is now.
                String shipDate = java.time.LocalDateTime.now().plusHours(1).withNano(0).toString();
                Map<?, ?> shipped = (Map<?, ?>) tools.call("update_sales_order", Map.of("id", id,
                        "revisionNumber", 1, "status", 5, "shipDate", shipDate)).get("item");
                assertEquals(2, ((Number) shipped.get("revisionNumber")).intValue());
                ToolException e = assertThrows(ToolException.class, () -> tools.call("add_order_line",
                        Map.of("salesOrder", id, "salesOrderVersion", 1, "product", 707, "orderQty", 1)));
                assertEquals(ToolException.Code.CONFLICT, e.code(), e.getMessage());
                assertEquals(false, e.details().get("conditionHolds"), "shipped: a logical conflict, do not retry");
            }
        }
    }
}
